using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.UI;using Cynthia.Card;
public static class MotionWork{public static void Run(){var cards=GwentMap.GetCards(isHasAgent:true).Where(c=>c.CardArtsId=="12210500"||c.CardArtsId=="203222").ToList();File.WriteAllLines("C:/UnityProjects/LegacyGwent/work/DynamicCards/MotionIntegrity/main-framing-cards.txt",cards.Select(c=>c.CardId+" "+c.CardArtsId+" "+c.Name));var editor=Resources.FindObjectsOfTypeAll<EditorInfo>().First(x=>x.gameObject.scene.IsValid());editor.MainUI.SetActive(false);editor.EditorUI.SetActive(true);editor.OpenEditor(false);editor.LeftSwitchMenu.anchoredPosition=new Vector2(-1700,0);editor.RightSwitchMenu.anchoredPosition=new Vector2(1700,0);editor.SetShowCardInfo(cards);editor.SelectSwitchUICard(cards.First());var go=UnityEngine.Object.Instantiate(editor.EditorListCardPrefab,editor.GetComponentInParent<Canvas>().transform,false);go.name="Local framing thumbnail";var rt=(RectTransform)go.transform;rt.anchorMin=rt.anchorMax=new Vector2(.5f,.5f);rt.anchoredPosition=new Vector2(0,-100);rt.sizeDelta=new Vector2(420,60);go.GetComponent<ListCardShowInfo>().SetCardInfo(cards.First().CardId);}}
